        this.json = json;
    }

    @KafkaListener(topics = "payment-settled", groupId = "orders")
    public void on(String message) {
        PaymentSettled event = parse(message);
        log.info("payment-settled attempt for order {}", event.orderId());
        orders.markPaid(event);
    }

    // ConversionException is one the error handler never retries, so a message
    // we cannot read goes straight to the DLT.
    private PaymentSettled parse(String message) {
        PaymentSettled event;
        try {
            event = json.readValue(message, PaymentSettled.class);
        } catch (JacksonException e) {
            throw new ConversionException("Not a PaymentSettled message", e);
        }
        if (event == null) {
            throw new ConversionException("Not a PaymentSettled message", null);
        }
        return event;
    }
